    }

    private without sharing class TicketQuerier {
        public static List<FB_Ticket__c> getOpenTickets() {
            return [SELECT Id, Name, Status__c, Priority__c, Internal_Notes__c FROM FB_Ticket__c WHERE Status__c = 'Open' ORDER BY Name];
        }
