public class RecordSearchService {
    public class SearchException extends Exception {}

    public static List<SObject> search(String objectApiName, List<String> fields, 
                                       Map<String, Object> filters, String orderByField, 
                                       Integer maxRows) {
        // Validate all inputs
        validateInputs(objectApiName, fields, filters, orderByField, maxRows);

        // Build and execute the query
        String query = buildQuery(objectApiName, fields, filters, orderByField, maxRows);

        try {
            return Database.query(query);
        } catch (Exception e) {
            throw new SearchException('Query execution failed: ' + e.getMessage());
        }
    }

    private static void validateInputs(String objectApiName, List<String> fields, 
                                       Map<String, Object> filters, String orderByField, 
                                       Integer maxRows) {
        // Validate object API name
        if (String.isBlank(objectApiName)) {
            throw new SearchException('Object API name cannot be blank');
        }

        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        Schema.SObjectType objectType = globalDescribe.get(objectApiName.toLowerCase());

        if (objectType == null) {
            throw new SearchException('Object does not exist: ' + objectApiName);
        }

        Schema.DescribeSObjectResult objectDescribe = objectType.getDescribe();
        Map<String, Schema.SObjectField> fieldMap = objectDescribe.fields.getMap();

        // Validate fields list
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('Fields list cannot be null or empty');
        }

        // Validate each field in the SELECT clause
        for (String field : fields) {
            if (String.isBlank(field)) {
                throw new SearchException('Field name cannot be blank');
            }

            Schema.SObjectField sObjectField = fieldMap.get(field.toLowerCase());
            if (sObjectField == null) {
                throw new SearchException('Field does not exist: ' + field);
            }

            Schema.DescribeFieldResult fieldDescribe = sObjectField.getDescribe();
            if (!fieldDescribe.isAccessible()) {
                throw new SearchException('Insufficient permissions to read field: ' + field);
            }
        }

        // Validate filter fields
        if (filters != null && !filters.isEmpty()) {
            for (String filterKey : filters.keySet()) {
                if (String.isBlank(filterKey)) {
                    throw new SearchException('Filter field name cannot be blank');
                }

                Schema.SObjectField sObjectField = fieldMap.get(filterKey.toLowerCase());
                if (sObjectField == null) {
                    throw new SearchException('Filter field does not exist: ' + filterKey);
                }

                Schema.DescribeFieldResult fieldDescribe = sObjectField.getDescribe();

                if (!fieldDescribe.isAccessible()) {
                    throw new SearchException('Insufficient permissions to read field: ' + filterKey);
                }

                if (!fieldDescribe.isFilterable()) {
                    throw new SearchException('Field cannot be filtered: ' + filterKey);
                }
            }
        }

        // Validate order by field
        if (!String.isBlank(orderByField)) {
            Schema.SObjectField sObjectField = fieldMap.get(orderByField.toLowerCase());
            if (sObjectField == null) {
                throw new SearchException('Order by field does not exist: ' + orderByField);
            }

            Schema.DescribeFieldResult fieldDescribe = sObjectField.getDescribe();

            if (!fieldDescribe.isAccessible()) {
                throw new SearchException('Insufficient permissions to read field: ' + orderByField);
            }

            if (!fieldDescribe.isSortable()) {
                throw new SearchException('Field cannot be sorted: ' + orderByField);
            }
        }

        // Validate maxRows
        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            throw new SearchException('maxRows must be between 1 and 200');
        }
    }

    private static String buildQuery(String objectApiName, List<String> fields, 
                                    Map<String, Object> filters, String orderByField, 
                                    Integer maxRows) {
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        Schema.SObjectType objectType = globalDescribe.get(objectApiName.toLowerCase());
        Schema.DescribeSObjectResult objectDescribe = objectType.getDescribe();
        Map<String, Schema.SObjectField> fieldMap = objectDescribe.fields.getMap();

        String query = 'SELECT Id';

        // Add requested fields
        for (String field : fields) {
            String actualFieldName = fieldMap.get(field.toLowerCase()).getDescribe().getName();
            query += ', ' + actualFieldName;
        }

        // Add FROM clause
        query += ' FROM ' + objectDescribe.getName();

        // Add WHERE clause if filters exist
        if (filters != null && !filters.isEmpty()) {
            query += ' WHERE ';
            List<String> whereConditions = new List<String>();

            for (String filterKey : filters.keySet()) {
                Schema.SObjectField sObjectField = fieldMap.get(filterKey.toLowerCase());
                String actualFieldName = sObjectField.getDescribe().getName();
                Object filterValue = filters.get(filterKey);
                Schema.DescribeFieldResult fieldDescribe = sObjectField.getDescribe();

                String condition = actualFieldName + ' = ' + 
                                 formatFilterValue(filterValue, fieldDescribe);
                whereConditions.add(condition);
            }

            query += String.join(whereConditions, ' AND ');
        }

        // Add ORDER BY clause if specified
        if (!String.isBlank(orderByField)) {
            Schema.SObjectField sObjectField = fieldMap.get(orderByField.toLowerCase());
            String actualFieldName = sObjectField.getDescribe().getName();
            query += ' ORDER BY ' + actualFieldName + ' ASC';
        }

        // Add LIMIT clause
        query += ' LIMIT ' + maxRows;

        return query;
    }

    private static String formatFilterValue(Object value, Schema.DescribeFieldResult fieldDescribe) {
        if (value == null) {
            return 'null';
        }

        Schema.DisplayType fieldType = fieldDescribe.getType();

        // Handle based on actual field type from schema
        if (fieldType == Schema.DisplayType.BOOLEAN) {
            return String.valueOf(value);
        } else if (fieldType == Schema.DisplayType.CURRENCY || 
                   fieldType == Schema.DisplayType.DOUBLE || 
                   fieldType == Schema.DisplayType.PERCENT) {
            return String.valueOf(value);
        } else if (fieldType == Schema.DisplayType.INTEGER) {
            return String.valueOf(value);
        } else if (fieldType == Schema.DisplayType.DATE) {
            return '\'' + String.valueOf(value) + '\'';
        } else if (fieldType == Schema.DisplayType.DATETIME) {
            return '\'' + String.valueOf(value) + '\'';
        } else if (fieldType == Schema.DisplayType.ID) {
            String idValue = String.valueOf(value);
            return '\'' + String.escapeSingleQuotes(idValue) + '\'';
        } else {
            // For STRING, TEXTAREA, EMAIL, PHONE, URL, PICKLIST, etc.
            String stringValue = String.valueOf(value);
            return '\'' + String.escapeSingleQuotes(stringValue) + '\'';
        }
    }
}
