public inherited sharing class AccountsSelector extends fflib_SObjectSelector {
    public AccountsSelector() {
        super();
        setDataAccess(DataAccess.USER_MODE);
    }

    public Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    public List<Schema.SObjectField> getSObjectFieldList() {
        List<Schema.SObjectField> fields = new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };

        // Dynamically add fields from Credit_Review field set
        Schema.FieldSet creditReviewFieldSet = Schema.SObjectType.Account.fieldSets.Credit_Review;
        for (Schema.FieldSetMember fsm : creditReviewFieldSet.getFields()) {
            fields.add(fsm.getSObjectField());
        }

        return fields;
    }

    public List<Account> selectById(Set<Id> accountIds) {
        return (List<Account>) selectSObjectsById(accountIds);
    }

    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        fflib_QueryFactory accountsQF = newQueryFactory();
        accountsQF.setCondition('Id IN :accountIds');

        // Build Contacts subquery from ContactsSelector's fields
        ContactsSelector contactsSelector = new ContactsSelector();
        List<String> contactFieldNames = new List<String>();
        for (Schema.SObjectField field : contactsSelector.getSObjectFieldList()) {
            contactFieldNames.add(field.getDescribe().getName());
        }

        String contactSubquery = '(SELECT ' + String.join(contactFieldNames, ', ') + ' FROM Contacts)';
        String soql = accountsQF.toSOQL() + ' ' + contactSubquery + ' WITH USER_MODE';

        return (List<Account>) Database.query(soql);
    }
}
