```apex
public class CaseSurveyJob implements Queueable {
    private List<Id> caseIds;

    public CaseSurveyJob(List<Id> caseIds) {
        this.caseIds = caseIds;
    }

    public void execute(QueueableContext context) {
        // Query all cases in the batch
        Map<Id, Case> cases = new Map<Id, Case>(
            [SELECT Id, CaseNumber, ContactId FROM Case WHERE Id IN :caseIds]
        );

        List<Task> tasksToInsert = new List<Task>();

        // Build tasks for all cases with contacts
        for (Id caseId : caseIds) {
            Case c = cases.get(caseId);
            if (c != null && c.ContactId != null) {
                Task t = new Task(
                    WhatId = c.Id,
                    WhoId = c.ContactId,
                    Subject = 'CSAT survey: ' + c.CaseNumber,
                    ActivityDate = System.today().addDays(2),
                    Status = 'Not Started'
                );
                tasksToInsert.add(t);
            }
        }

        // Insert with allOrNone=false so one task failure doesn't block the others
        if (!tasksToInsert.isEmpty()) {
            Database.insert(tasksToInsert, false);
        }
    }
}
