```javascript
import { LightningElement, api } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label = '';
    @api options = [];

    _value = '';
    activeIndex = 0;

    @api
    set value(newValue) {
        this._value = newValue;
        this.updateActiveIndexFromValue();
    }

    get value() {
        return this._value;
    }

    get computedOptions() {
        return this.options.map((option) => ({
            ...option,
            id: `option-${option.value}`,
            isSelected: option.value === this._value
        }));
    }

    updateActiveIndexFromValue() {
        const foundIndex = this.options.findIndex(opt => opt.value === this._value);
        if (foundIndex !== -1) {
            this.activeIndex = foundIndex;
        } else {
            this.activeIndex = this.options.length > 0 ? 0 : -1;
        }
    }

    connectedCallback() {
        this.updateActiveIndexFromValue();
    }

    get activeDescendant() {
        if (this.activeIndex >= 0 && this.activeIndex < this.options.length) {
            return `option-${this.options[this.activeIndex].value}`;
        }
        return '';
    }

    handleKeyDown(event) {
        const { key } = event;

        if (key === 'ArrowDown') {
            event.preventDefault();
            if (this.activeIndex < this.options.length - 1) {
                this.activeIndex++;
            }
        } else if (key === 'ArrowUp') {
            event.preventDefault();
            if (this.activeIndex > 0) {
                this.activeIndex--;
            }
        } else if (key === 'Home') {
            event.preventDefault();
            if (this.options.length > 0) {
                this.activeIndex = 0;
            }
        } else if (key === 'End') {
            event.preventDefault();
            if (this.options.length > 0) {
                this.activeIndex = this.options.length - 1;
            }
        } else if (key === 'Enter' || key === ' ') {
            event.preventDefault();
            this.selectActive();
        }
    }

    selectActive() {
        if (this.activeIndex >= 0 && this.activeIndex < this.options.length) {
            const newValue = this.options[this.activeIndex].value;
            if (newValue !== this._value) {
                this._value = newValue;
                this.dispatchEvent(
                    new CustomEvent('change', {
                        detail: { value: newValue },
                        bubbles: true,
                        composed: true
                    })
                );
            }
        }
    }

    handleOptionClick(event) {
        const clickedValue = event.currentTarget.getAttribute('data-value');
        const index = this.options.findIndex(opt => opt.value === clickedValue);
        if (index !== -1) {
            this.activeIndex = index;
            this.selectActive();
        }
    }
}
