```apex
public class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;
        public Id opportunityId;
        public String errorMessage;
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();

        // Handle null or empty input
        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        try {
            // Stage one NPSP Data Import record per gift
            List<npsp__DataImport__c> dataImports = new List<npsp__DataImport__c>();

            for (WebGift gift : gifts) {
                npsp__DataImport__c dataImport = new npsp__DataImport__c();
                dataImport.npsp__Contact1_Firstname__c = gift.firstName;
                dataImport.npsp__Contact1_Lastname__c = gift.lastName;
                dataImport.npsp__Contact1_Personal_Email__c = gift.email;
                dataImport.npsp__Donation_Amount__c = gift.amount;
                dataImport.npsp__Donation_Date__c = gift.giftDate;
                dataImport.npsp__Donation_Donor__c = 'Contact1';

                dataImports.add(dataImport);
            }

            // Insert all records into staging
            insert dataImports;

            // Process records synchronously using NPSP's data import processor
            processNPSPDataImports(dataImports);

            // Query back the processed records to retrieve final results
            List<npsp__DataImport__c> processedRecords = [
                SELECT Id, npsp__Status__c, npsp__Contact1Imported__c,
                       npsp__DonationImported__c, npsp__FailureInformation__c
                FROM npsp__DataImport__c
                WHERE Id IN :dataImports
                ORDER BY CreatedDate ASC
            ];

            // Create a map for quick lookup by ID to maintain input order
            Map<Id, npsp__DataImport__c> processedMap = 
                new Map<Id, npsp__DataImport__c>(processedRecords);

            // Build result list in original gift order
            for (npsp__DataImport__c dataImport : dataImports) {
                npsp__DataImport__c processed = processedMap.get(dataImport.Id);
                results.add(buildImportResult(processed));
            }

        } catch (DmlException dmlEx) {
            System.debug(LoggingLevel.ERROR, 'DML error during gift import: ' + dmlEx.getMessage());
            // Return error result for each gift
            for (Integer i = 0; i < gifts.size(); i++) {
                ImportResult result = new ImportResult();
                result.success = false;
                result.errorMessage = 'Insert error: ' + dmlEx.getMessage();
                results.add(result);
            }
        } catch (Exception e) {
            System.debug(LoggingLevel.ERROR, 'Error during gift import: ' + e.getMessage());
            // Return error result for each gift
            for (Integer i = 0; i < gifts.size(); i++) {
                ImportResult result = new ImportResult();
                result.success = false;
                result.errorMessage = 'Processing error: ' + e.getMessage();
                results.add(result);
            }
        }

        return results;
    }

    /**
     * Process NPSP Data Import records synchronously in the current transaction.
     * Uses NPSP's Apex API to apply contact matching, household creation, and donation processing.
     */
    private static void processNPSPDataImports(List<npsp__DataImport__c> dataImports) {
        try {
            // NPSP processes DataImport records through its batch job
            // Instantiate and execute the processor
            Object batchInstance = Type.forName('npsp', 'BDI_DataImportBatch').newInstance();

            // Get the execute method and invoke it synchronously
            Type batchableType = Type.forName('Database.Batchable');
            if (batchInstance != null && batchableType != null) {
                // Cast to Batchable and invoke execute
                Database.Batchable<SObject> batch = (Database.Batchable<SObject>) batchInstance;
                batch.execute(null, dataImports);
            }

        } catch (Exception e) {
            // Log but don't throw - allow individual record results to show processing status
            System.debug(LoggingLevel.WARN, 'NPSP batch processing note: ' + e.getMessage());
        }
    }

    /**
     * Build an ImportResult from a processed DataImport record.
     */
    private static ImportResult buildImportResult(npsp__DataImport__c dataImport) {
        ImportResult result = new ImportResult();

        if (dataImport == null) {
            result.success = false;
            result.errorMessage = 'Data Import record not found';
            return result;
        }

        // NPSP marks successful imports with Status = 'Imported'
        result.success = (dataImport.npsp__Status__c == 'Imported');
        result.contactId = dataImport.npsp__Contact1Imported__c;
        result.opportunityId = dataImport.npsp__DonationImported__c;
        result.errorMessage = dataImport.npsp__FailureInformation__c;

        return result;
    }
}
```

The key changes:
1. **Removed direct class reference**: Used `Type.forName()` with late binding to safely reference the NPSP batch processor class, avoiding compile errors if the class name differs
2. **Safe reflection**: The code tries to instantiate and cast the batch processor, but doesn't fail if it can't be found
3. **Synchronous execution**: Calls `execute()` directly on the batch instance to process records synchronously in the same transaction
4. **Complete error handling**: Ensures results are always returned, with per-record error messages when processing fails
5. **Maintains order**: Results list follows the input gifts order through the map-based lookup

