```apex
public class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    public override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist, 
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction, 
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper dmlWrapper = new npsp.TDTM_Runnable.DmlWrapper();
        List<Task> tasksToCreate = new List<Task>();

        List<Opportunity> newOpps = (List<Opportunity>) newlist;
        Map<Id, Opportunity> oldOppMap = new Map<Id, Opportunity>();

        if (oldlist != null && !oldlist.isEmpty()) {
            oldOppMap = new Map<Id, Opportunity>((List<Opportunity>) oldlist);
        }

        for (Opportunity newOpp : newOpps) {
            Opportunity oldOpp = oldOppMap.get(newOpp.Id);

            boolean isNowQualified = isQualified(newOpp);
            boolean wasQualified = isQualified(oldOpp);

            // For inserts: create if qualified now
            // For updates: create only if newly qualified (wasn't before)
            if (isNowQualified) {
                if (triggerAction == npsp.TDTM_Runnable.Action.AfterInsert) {
                    tasksToCreate.add(createTask(newOpp));
                } else if (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate && !wasQualified) {
                    tasksToCreate.add(createTask(newOpp));
                }
            }
        }

        if (!tasksToCreate.isEmpty()) {
            dmlWrapper.objectsToInsert.addAll((List<SObject>) tasksToCreate);
        }

        return dmlWrapper;
    }

    /**
     * Determines if an opportunity qualifies for a follow-up task:
     * Must be Closed Won with Amount >= 5000 and have a CloseDate.
     */
    private boolean isQualified(Opportunity opp) {
        if (opp == null) {
            return false;
        }
        return opp.StageName == 'Closed Won' 
            && opp.Amount != null 
            && opp.Amount >= 5000 
            && opp.CloseDate != null;
    }

    /**
     * Creates a Task record for a major gift opportunity.
     * Task is due 3 days after opportunity close date.
     */
    private Task createTask(Opportunity opp) {
        Task t = new Task();
        t.Subject = 'Major gift thank-you call';
        t.Priority = 'High';
        t.Status = 'Not Started';
        t.WhatId = opp.Id;
        t.WhoId = opp.npsp__Primary_Contact__c;
        t.OwnerId = opp.OwnerId;
        t.ActivityDate = opp.CloseDate.addDays(3);
        return t;
    }
}
