public with sharing class TA_Account_CreateOnboardingTask implements TriggerAction.AfterInsert {
    public void afterInsert(List<SObject> triggerNew) {
        List<Task> tasksToInsert = new List<Task>();

        for (SObject sObj : triggerNew) {
            Account acc = (Account) sObj;

            // Check if the account type matches the onboarding criteria
            if (acc.Type == 'Customer - Direct' || acc.Type == 'Customer - Channel') {
                Task t = new Task(
                    Subject = 'Onboard new customer',
                    WhatId = acc.Id,
                    OwnerId = acc.OwnerId,
                    ActivityDate = System.today().addDays(7),
                    Status = 'Not Started',
                    Priority = 'Normal'
                );
                tasksToInsert.add(t);
            }
        }

        // Only perform DML if there are tasks to insert
        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
