```apex
public class TA_Contact_PreventDuplicateEmail implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    public void beforeInsert(List<SObject> triggerNew) {
        List<Contact> contacts = (List<Contact>) triggerNew;
        validateDuplicateEmails(contacts, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Contact> newContacts = (List<Contact>) triggerNew;
        List<Contact> oldContacts = (List<Contact>) triggerOld;
        Map<Id, Contact> oldContactsMap = new Map<Id, Contact>(oldContacts);

        // Filter to only contacts whose Email or AccountId changed
        List<Contact> changedContacts = new List<Contact>();

        for (Contact newContact : newContacts) {
            Contact oldContact = oldContactsMap.get(newContact.Id);
            if (oldContact.Email != newContact.Email || oldContact.AccountId != newContact.AccountId) {
                changedContacts.add(newContact);
            }
        }

        if (!changedContacts.isEmpty()) {
            validateDuplicateEmails(changedContacts, oldContactsMap);
        }
    }

    private void validateDuplicateEmails(List<Contact> contacts, Map<Id, Contact> oldContactsMap) {
        // Collect account IDs and emails to check
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();

        for (Contact contact : contacts) {
            if (contact.AccountId != null && contact.Email != null) {
                accountIds.add(contact.AccountId);
                emails.add(contact.Email.toLowerCase());
            }
        }

        if (accountIds.isEmpty() || emails.isEmpty()) {
            return;
        }

        // Single SOQL query to get all existing contacts
        List<Contact> existingContacts = [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds AND Email IN :emails
        ];

        // Build a map for quick lookup
        Map<String, List<Contact>> accountEmailToDuplicates = new Map<String, List<Contact>>();
        for (Contact contact : existingContacts) {
            String key = contact.AccountId + '||' + contact.Email.toLowerCase();
            if (!accountEmailToDuplicates.containsKey(key)) {
                accountEmailToDuplicates.put(key, new List<Contact>());
            }
            accountEmailToDuplicates.get(key).add(contact);
        }

        // Track which account+email combinations have been seen in this batch
        Set<String> seenInBatch = new Set<String>();

        for (Contact contact : contacts) {
            if (contact.AccountId == null || contact.Email == null) {
                continue;
            }

            String key = contact.AccountId + '||' + contact.Email.toLowerCase();

            // Check if already seen in this batch (first one is accepted, later ones rejected)
            if (seenInBatch.contains(key)) {
                contact.addError('Another contact on this account already uses this email address.');
                continue;
            }

            // Check if exists in database (excluding self on update)
            List<Contact> duplicates = accountEmailToDuplicates.get(key);
            if (duplicates != null && !duplicates.isEmpty()) {
                // On update, check if any of the duplicates is not self
                Boolean hasOtherDuplicate = false;
                if (oldContactsMap != null) {
                    // This is an update, exclude self
                    for (Contact dup : duplicates) {
                        if (dup.Id != contact.Id) {
                            hasOtherDuplicate = true;
                            break;
                        }
                    }
                } else {
                    // This is an insert
                    hasOtherDuplicate = true;
                }

                if (hasOtherDuplicate) {
                    contact.addError('Another contact on this account already uses this email address.');
                    continue;
                }
            }

            // Mark this combination as seen in batch
            seenInBatch.add(key);
        }
    }
}
